
[data-theme="synthwave"] {
  --bg-primary: #17051d;
  --bg-secondary: #290f38;
  --bg-tertiary: #3a1550;
  --bg-bubble-user: #ff4ad8;
  --bg-bubble-agent: #290f38;
  --border-color: #5a2a6e;
  --text-primary: #fff3ff;
  --text-secondary: #e1aeea;
  --text-muted: #9d6bc4;
  --accent: #ff4ad8;
  --accent-glow: rgba(255, 74, 216, 0.3);
  --accent-hover: #f22ccc;
  --header-gradient: linear-gradient(135deg, #17051d 0%, #290f38 50%, #17051d 100%);
  --button-gradient: linear-gradient(135deg, #f22ccc 0%, #ff4ad8 100%);
  --theme-name: "Synthwave Retro";
  --bg-image-desktop: url("data:image/png;base64,");
  --bg-image-mobile: url("data:image/png;base64,");
}
